contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // initialMin - value to set as MinSum before initialization
    // newMin - value attempted to set after initialization (should be ignored in P)
    // callerFunds - ether to deposit into this test contract so it can call payable functions if needed
    function run(uint initialMin, uint newMin, uint callerFunds) public {
        // fund check for potential payable calls (not used here but allowed by rules)
        require(address(this).balance >= callerFunds);

        // 1) Set MinSum the first time (before initialization)
        c.SetMinSum(initialMin);

        // 2) Mark contract initialized
        c.Initialized();

        // 3) Attempt to change MinSum after initialization
        c.SetMinSum(newMin);

        // Observe MinSum via public getter and assert it did not change after initialization
        // On original contract P this must hold: MinSum == initialMin
        // On mutant M (which allows change) this can be false when newMin != initialMin
        assert(c.MinSum() == initialMin);
    }

    // Allow contract to receive Ether for callerFunds requirement if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: attempt to SetMinSum before calling Initialized()
    // The rule: when intitalized is false, SetMinSum does not revert and updates MinSum.
    // We express this by calling SetMinSum and then reading MinSum; on P the call succeeds and MinSum equals the input, on M the call reverts and test fails.
    function check(uint newMin) public {
        // Ensure the call does not revert and takes effect
        c.SetMinSum(newMin);
        uint observed = c.MinSum();
        assert(observed == newMin);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint newMin, uint collectAmount) public payable {
        require(true);
        // First mark the contract initialized (in original this prevents future SetMinSum)
        c.Initialized();
        // Now call Collect as in the provided sequence (we only need to invoke it to match the observed sequence)
        c.Collect(collectAmount);
        // After initialization, SetMinSum should not be able to change MinSum in the original;
        // read MinSum before and after attempting to set it via the public setter to observe any change
        uint before = c.MinSum();
        // attempt to set MinSum; in original this should revert (or be no-op due to require), but we still call it
        // We capture whether it reverts by using low-level call on address(c) with encoded selector
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMin));
        uint after = c.MinSum();
        // General rule: if the setter succeeded (ok==true), then before must equal after (no change);
        // In the original contract (P) the setter should not succeed after Initialized(), so either ok==false or the value must be unchanged.
        assert(!ok || before == after);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint newMin) public payable {
        // precondition: none needed beyond being able to call functions
        // 1) initialize the contract
        c.Initialized();
        // record MinSum after initialization
        uint before = c.MinSum();
        // 2) attempt to set MinSum (in original this should revert; but we still call it)
        bool didRevert;
        // perform low-level call to capture success/failure without reverting this test
        (didRevert, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMin));
        // read MinSum after the attempt
        uint after = c.MinSum();
        // In the original contract SetMinSum will revert when initialized, so MinSum must be unchanged.
        // The property: either the call reverted (as in original) and MinSum is unchanged, or if it didn't revert, then MinSum must equal the new value.
        // For the original contract this simplifies to: call reverts and after==before. The mutant violates that because it allows change.
        assert(didRevert && after == before);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint newMin) public payable {
        // initialize contract so original disallows SetMinSum afterwards
        c.Initialized();
        uint before = c.MinSum();
        // attempt to set MinSum; in the original this call should revert and leave MinSum unchanged
        bool ok;
        // capture whether call succeeded without reverting
        (ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMin));
        uint after = c.MinSum();
        // General rule: after initialization, MinSum must remain equal to its previous value (i.e., SetMinSum cannot succeed to change it)
        assert(after == before && ok == false);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint putAmount, uint lockTime, uint collectAmount, uint newMin) public payable {
        require(address(this).balance >= putAmount);
        // 1) Put some funds into the caller's account so Collect can act
        c.Put{value: putAmount}(lockTime);
        // 2) Read MinSum before initialization
        uint beforeInitMin = c.MinSum();
        // 3) Mark contract initialized; in original this prevents SetMinSum from succeeding
        c.Initialized();
        // 4) Attempt to set MinSum after initialization (original will revert, mutant will succeed)
        bool didRevert = false;
        // capture revert by low-level call
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMin));
        didRevert = !ok;
        // 5) Call Collect which is the observable action in the original counterexample
        // Ensure enough balance for transferring if needed
        c.Collect(collectAmount);
        // In the original contract, SetMinSum reverts after Initialized(), so MinSum must remain equal to beforeInitMin.
        // In the mutant SetMinSum succeeds, changing MinSum possibly to newMin. We assert the general rule that if SetMinSum reverted then MinSum is unchanged.
        assert(didRevert == (c.MinSum() == beforeInitMin));
    }
    receive() external payable { }
}

