contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: actor address and amounts. We let the fuzzer pick actor and two amounts.
    function testFuzz_property(address actor, uint256 putAmt, uint256 collectAmt) public {
        // Keep values reasonable but wide
        vm.assume(actor != address(0));
        putAmt = bound(putAmt, 0, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // ensure actor has funds to put
        vm.deal(actor, putAmt + 1);

        // initial MinSum should be 0
        uint256 before = c.MinSum();

        // actor puts funds (calls Put via fallback or direct) — use Put via explicit call
        vm.startPrank(actor);
        if (putAmt > 0) {
