contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive sequence: set MinSum, set LogFile, initialize, deposit, then attempt Collect.
    // Parameters:
    // - minSum: value to set as MinSum
    // - deposit: amount of wei to send to Put
    // - withdraw: amount to attempt to Collect
    // We observe acc balance before and after Collect via the public Acc getter.
    function run(uint minSum, uint deposit, uint withdraw, address logAddr) public payable {
        require(address(this).balance >= deposit, "need deposit funds");
        // initialize contract parameters (must be done before Initialized())
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // get holder before deposit
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // deposit funds
        c.Put{value: deposit}(0);

        // attempt to collect withdraw amount
        c.Collect(withdraw);

        // get holder after collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // Rule: afterBalance must be <= beforeBalance + deposit (i.e., Collect cannot increase stored balance)
        // This holds in original P because non-reentrant collect only reduces balance; if modifier is removed, reentrancy can lead to an increase during nested calls.
        assert(afterBalance <= beforeBalance + deposit);
    }

    // allow receiving Ether for the test
    receive() external payable {}
}

