        // We observe MinSum before the Collect call.
        uint beforeMin = c.MinSum();
        require(beforeMin != 0, "MinSum must be nonzero");

        // Call Collect as the test caller. This is the call where reentrancy in M could allow
        // an attacker to change MinSum by calling SetMinSum during reentry. In P this is prevented.
        c.Collect(collectAmount);

        // After the call, MinSum must remain unchanged for the original contract P.
        uint afterMin = c.MinSum();
        assert(afterMin == beforeMin);
    }

    // no special receive logic needed
    receive() external payable { }
}

contract InvMutTest {
    C c;
    // we will perform a Collect which in the mutant can reenter and change MinSum;
    // to trigger reentrancy we make this contract able to receive ether and re-call c.Collect from receive().
    // Parameters: amount to attempt to collect (am), and a deposit amount to ensure balance >= MinSum condition (dep).
    uint public am_global;
    constructor(C _c) { c = _c; }

    receive() external payable {
        // reenter: during Collect's external call to this contract, invoke SetMinSum to a different value
        // (attempting to change MinSum). We call Initialized first is not possible here, so we just call SetMinSum
        // This call will succeed only in the mutant where nonReentrant_ is a no-op; in original it would revert due to lock.
        // Use a different value than current MinSum to observe change.
        // We must not assume ownership; SetMinSum has no access control in C so it's callable by anyone.
        // Call SetMinSum with value 1 to change it if possible.
        // Note: we keep calls top-level only in run(); this receive() is allowed as callback.
        c.SetMinSum(1);
    }

    function run(uint dep, uint am) public payable {
        require(address(this).balance >= dep + am);
        // Precondition: deposit enough to meet MinSum and allow Collect to proceed later.
        // Record MinSum before
        uint before = c.MinSum();
        am_global = am;

        // First, deposit funds so that c.Acc[this].balance >= MinSum and >= am, and set unlockTime in past by using 0
        // Call Put via fallback or Put directly; Put accepts lockTime param. We must send dep value.
        c.Put{value: dep}(0);

        // Now call Collect which will send ether to this contract and thus trigger receive reentry attempt to SetMinSum(1).
        c.Collect(am);

        uint after = c.MinSum();
        // General rule: Collect must not change MinSum (i.e., after == before).
        assert(after == before);
    }
}

