        c.Collect(am);

        // Read MinSum after the call
        uint after = c.MinSum();

        // In the original contract (with working nonReentrant_), MinSum cannot be changed by a single external Collect call.
        // Assert that MinSum remains the same. This is a general rule over parameters and observable state.
