contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We will try to trigger any reentrancy that could change MinSum by calling Collect once.
    // Parameters:
    // - am: amount to attempt to collect
    // Precondition: true (no extra requirements)
    function run(uint am) public payable {
        require(true);
        uint before = c.MinSum();
        // single external state-changing call which previously was protected by nonReentrant_
        c.Collect(am);
        uint afterMin = c.MinSum();
        // In the original, nonReentrant_ prevents reentrant calls that could change MinSum, so MinSum must stay equal.
        assert(afterMin == before);
