        // Call Collect on c; attacker will be msg.sender inside and try to trigger reentrancy
        c.Collect(collectAmt);

        // Exactly one assertion: in the correct contract (with nonReentrant_) MinSum must remain unchanged
        // The buggy contract (no-op modifier) can have MinSum changed by reentrant behavior; the fuzzer may find such inputs
        assertTrue(c.MinSum() == beforeMin);
    }
